		const { join } = await import('path');
		const offenders: string[] = [];
		function walk(dir: string): void {
			for (const entry of readdirSync(dir)) {
				const full = join(dir, entry);
				if (statSync(full).isDirectory()) { walk(full); continue; }
				if (!full.endsWith('.ts')) continue;
				const content = readFileSync(full, 'utf8');
				if (content.includes('requestUrl') && !full.includes('collection\\arxivClient.ts') && !full.includes('collection/arxivClient.ts') && !full.includes('collection\\semanticScholarClient.ts') && !full.includes('collection/semanticScholarClient.ts')) {
					offenders.push(full);
				}
			}
		}
		walk(join(process.cwd(), 'src'));
